Algorithm Frijol
  Define altura As Integer;
  Read altura;
  Define crecimiento As Integer <- 1;
  Define dias As Integer <- 0;
  While altura < 100 Do
    altura <- altura + crecimiento;
    crecimiento <- crecimiento * 2;
    dias <- dias + 1;
  EndWhile
  Write dias;
EndAlgorithm
